7	import fs from 'node:fs';
8	import path from 'node:path';
9	import { glob } from 'glob';
10	
11	import {
12	  analyzeEvalSource,
13	  type EvalCaseRecord,
14	  type EvalFileAnalysis,
15	  type EvalAnalysisDiagnostic,
16	  type EvalPolicy,
17	} from './eval-analysis.js';
18	
19	export interface InventoryResult {
20	  totalFiles: number;
21	  totalCases: number;
22	  files: EvalFileAnalysis[];
23	  cases: readonly EvalCaseRecord[];
24	  diagnostics: readonly EvalAnalysisDiagnostic[];
25	}
26	
27	/**
28	 * Discovers all eval files under the given repo root and runs
29	 * the static analyzer on each, returning the aggregated results.
30	 */
31	export async function collectInventory(
32	  repoRoot: string,
33	): Promise<InventoryResult> {
34	  const evalsDir = path.join(repoRoot, 'evals');
35	  const pattern = '**/*.eval.{ts,tsx}';
36	
37	  const evalFiles = await glob(pattern, {
38	    cwd: evalsDir,
39	    absolute: true,
40	    nodir: true,
41	  });
42	
43	  evalFiles.sort();
44	
45	  const files: EvalFileAnalysis[] = [];
46	  const allCases: EvalCaseRecord[] = [];
47	  const allDiagnostics: EvalAnalysisDiagnostic[] = [];
48	
49	  for (const filePath of evalFiles) {
50	    const sourceText = await fs.promises.readFile(filePath, 'utf-8');
51	    const analysis = analyzeEvalSource(sourceText, { filePath, repoRoot });
52	    files.push(analysis);
53	    allCases.push(...analysis.cases);
54	    allDiagnostics.push(...analysis.diagnostics);
55	  }
56	
57	  return {
58	    totalFiles: files.length,
59	    totalCases: allCases.length,
60	    files,
61	    cases: allCases,
62	    diagnostics: allDiagnostics,
63	  };
64	}
65	
66	/**
67	 * Formats an InventoryResult into a human-readable report string.
68	 */
69	export function formatInventoryReport(result: InventoryResult): string {
70	  const lines: string[] = [];
71	
72	  lines.push('Eval Inventory');
73	  lines.push('══════════════');
74	  lines.push('');
75	  lines.push(
76	    `${result.totalFiles} files · ${result.totalCases} cases · ${result.diagnostics.length} diagnostics`,
77	  );
78	  lines.push('');
79	
80	  // --- By Policy ---
81	  lines.push('By Policy');
82	  lines.push('─────────');
83	
84	  const byPolicy = groupBy(result.cases, (c) => c.policy);
85	  const policyOrder: EvalPolicy[] = [
86	    'ALWAYS_PASSES',
87	    'USUALLY_PASSES',
88	    'USUALLY_FAILS',
89	    'unknown',
90	  ];
91	
92	  for (const policy of policyOrder) {
93	    const cases = byPolicy.get(policy);
94	    if (!cases || cases.length === 0) {
95	      continue;
96	    }
97	
98	    lines.push(`${policy} (${cases.length} cases)`);
99	
100	    const byFile = groupBy(cases, (c) => c.relativePath);
101	    for (const [filePath, fileCases] of byFile) {
102	      lines.push(`  ${filePath}`);
103	      for (const evalCase of fileCases) {
104	        lines.push(`    • ${evalCase.name} [${evalCase.helperName}]`);
105	      }
106	    }
107	    lines.push('');
108	  }
109	
110	  // --- By Suite ---
111	  lines.push('By Suite');
112	  lines.push('────────');
113	
114	  const bySuite = groupBy(result.cases, (c) => c.suiteName ?? '(no suite)');
115	  const suiteNames = [...bySuite.keys()].sort((a, b) => {
116	    if (a === b) return 0;
117	    if (a === '(no suite)') return 1;
118	    if (b === '(no suite)') return -1;
119	    return a.localeCompare(b, 'en');
120	  });
121	
122	  for (const suite of suiteNames) {
123	    const cases = bySuite.get(suite)!;
124	    lines.push(`${suite} (${cases.length} cases)`);
125	
126	    for (const evalCase of cases) {
127	      lines.push(
128	        `  • ${evalCase.name} [${evalCase.relativePath}] (${evalCase.policy})`,
129	      );
130	    }
131	    lines.push('');
132	  }
133	
134	  // --- Diagnostics ---
135	  if (result.diagnostics.length > 0) {
136	    const filePaths = new Map<string, string>();
137	    for (const f of result.files) {
138	      filePaths.set(f.filePath, f.relativePath);
139	    }
140	
141	    lines.push('Diagnostics');
142	    lines.push('───────────');
143	    for (const diagnostic of result.diagnostics) {
144	      const displayPath =
145	        diagnostic.filePath === '<inline>'
146	          ? diagnostic.filePath
147	          : (filePaths.get(diagnostic.filePath) ?? diagnostic.filePath);
148	      lines.push(
149	        `⚠ ${displayPath}:${diagnostic.location.line}:${diagnostic.location.column} — ${diagnostic.message}`,
150	      );
151	    }
152	    lines.push('');
153	  }
154	
155	  return lines.join('\n');
156	}
157	
158	function groupBy<T>(
159	  items: readonly T[],
160	  keyFn: (item: T) => string,
161	): Map<string, T[]> {
162	  const groups = new Map<string, T[]>();
163	  for (const item of items) {
164	    const key = keyFn(item);
165	    const group = groups.get(key);
166	    if (group) {
167	      group.push(item);
168	    } else {
169	      groups.set(key, [item]);
170	    }
171	  }
172	  return groups;
173	}
