7	import path from 'node:path';
8	import * as ts from 'typescript';
9	
10	export const BASE_EVAL_HELPERS = [
11	  'evalTest',
12	  'appEvalTest',
13	  'componentEvalTest',
14	] as const;
15	
16	export type BaseEvalHelper = (typeof BASE_EVAL_HELPERS)[number];
17	export type EvalHelperName = BaseEvalHelper | string;
18	export type EvalPolicy =
19	  | 'ALWAYS_PASSES'
20	  | 'USUALLY_PASSES'
21	  | 'USUALLY_FAILS'
22	  | 'unknown';
23	
24	export interface EvalSourceLocation {
25	  line: number;
26	  column: number;
27	}
28	
29	export interface EvalAnalysisDiagnostic {
30	  severity: 'warning';
31	  message: string;
32	  filePath: string;
33	  location: EvalSourceLocation;
34	}
35	
36	export interface EvalCaseRecord {
37	  filePath: string;
38	  relativePath: string;
39	  helperName: EvalHelperName;
40	  baseHelperName: BaseEvalHelper | 'unknown';
41	  policy: EvalPolicy;
42	  name: string;
43	  suiteName?: string;
44	  suiteType?: string;
45	  timeout?: number;
46	  hasFiles: boolean;
47	  hasPrompt: boolean;
48	  location: EvalSourceLocation;
49	}
50	
51	export interface EvalFileAnalysis {
52	  filePath: string;
53	  relativePath: string;
54	  helpers: Record<string, BaseEvalHelper | 'unknown'>;
55	  cases: readonly EvalCaseRecord[];
56	  diagnostics: readonly EvalAnalysisDiagnostic[];
57	}
58	
59	export interface AnalyzeEvalSourceOptions {
60	  filePath?: string;
61	  repoRoot?: string;
62	}
63	
64	export function analyzeEvalSource(
65	  sourceText: string,
66	  options: AnalyzeEvalSourceOptions = {},
67	): EvalFileAnalysis {
68	  const filePath = options.filePath ?? '<inline>';
69	  const relativePath = getRelativePath(filePath, options.repoRoot);
70	  const sourceFile = ts.createSourceFile(
71	    filePath,
72	    sourceText,
73	    ts.ScriptTarget.Latest,
74	    true,
75	    getScriptKind(filePath),
76	  );
77	
78	  const helpers = collectHelperMappings(sourceFile);
79	  const diagnostics: EvalAnalysisDiagnostic[] = [];
80	  const cases: EvalCaseRecord[] = [];
81	
82	  collectEvalCalls(sourceFile, helpers, (callExpression, helperName) => {
83	    const args = callExpression.arguments;
84	    const policyArg = args[0];
85	    const evalCaseArg = args[1];
86	    const policy = policyArg ? getStringLiteralValue(policyArg) : undefined;
87	    const evalCase =
88	      evalCaseArg && ts.isObjectLiteralExpression(evalCaseArg)
89	        ? evalCaseArg
90	        : undefined;
91	
92	    if (!policy || !isEvalPolicy(policy)) {
93	      diagnostics.push({
94	        severity: 'warning',
95	        message: `Could not statically resolve policy for ${helperName} call.`,
96	        filePath,
97	        location: getLocation(sourceFile, policyArg ?? callExpression),
98	      });
99	    }
100	
101	    if (!evalCase) {
102	      diagnostics.push({
103	        severity: 'warning',
104	        message: `Could not statically resolve eval case object for ${helperName} call.`,
105	        filePath,
106	        location: getLocation(sourceFile, evalCaseArg ?? callExpression),
107	      });
108	      return;
109	    }
110	
111	    const name = getStaticStringProperty(evalCase, 'name');
112	    if (!name) {
113	      diagnostics.push({
114	        severity: 'warning',
115	        message: `Could not statically resolve eval case name for ${helperName} call.`,
116	        filePath,
117	        location: getLocation(sourceFile, evalCase),
118	      });
119	    }
120	
121	    cases.push({
122	      filePath,
123	      relativePath,
124	      helperName,
125	      baseHelperName: helpers[helperName] ?? 'unknown',
126	      policy: isEvalPolicy(policy) ? policy : 'unknown',
127	      name: name ?? '<unknown>',
128	      suiteName: getStaticStringProperty(evalCase, 'suiteName'),
129	      suiteType: getStaticStringProperty(evalCase, 'suiteType'),
130	      timeout: getStaticNumberProperty(evalCase, 'timeout'),
131	      hasFiles: hasProperty(evalCase, 'files'),
132	      hasPrompt: hasProperty(evalCase, 'prompt'),
133	      location: getLocation(sourceFile, callExpression),
134	    });
135	  });
136	
137	  cases.sort(compareEvalCases);
138	
139	  return {
140	    filePath,
141	    relativePath,
142	    helpers,
143	    cases,
144	    diagnostics: diagnostics.sort(compareDiagnostics),
145	  };
146	}
147	
148	function collectHelperMappings(
149	  sourceFile: ts.SourceFile,
150	): Record<string, BaseEvalHelper | 'unknown'> {
151	  const helpers: Record<string, BaseEvalHelper | 'unknown'> = {};
152	  for (const helper of BASE_EVAL_HELPERS) {
153	    helpers[helper] = helper;
154	  }
155	
156	  for (const alias of collectImportedHelperAliases(sourceFile)) {
157	    helpers[alias.name] = alias.baseHelper;
158	  }
159	
160	  let changed = true;
161	  while (changed) {
162	    changed = false;
163	
164	    const visit = (node: ts.Node) => {
165	      const name = getFunctionLikeBindingName(node);
166	      if (name && !helpers[name]) {
167	        const functionNode = getFunctionLikeNode(node);
168	        if (functionNode) {
169	          const baseHelper = findCalledHelper(functionNode, helpers);
170	          if (
171	            baseHelper &&
172	            helpers[baseHelper] &&
173	            helpers[baseHelper] !== 'unknown'
174	          ) {
175	            helpers[name] = helpers[baseHelper];
176	            changed = true;
177	          }
178	        }
179	      }
180	      ts.forEachChild(node, visit);
181	    };
182	
183	    visit(sourceFile);
184	  }
185	
186	  return helpers;
187	}
188	
189	function collectImportedHelperAliases(sourceFile: ts.SourceFile) {
190	  const aliases: Array<{ name: string; baseHelper: BaseEvalHelper }> = [];
191	
192	  for (const statement of sourceFile.statements) {
193	    if (
194	      !ts.isImportDeclaration(statement) ||
195	      !statement.importClause?.namedBindings ||
196	      !ts.isNamedImports(statement.importClause.namedBindings)
197	    ) {
198	      continue;
199	    }
200	
201	    for (const element of statement.importClause.namedBindings.elements) {
202	      const importedName = element.propertyName?.text ?? element.name.text;
203	      if (isBaseEvalHelper(importedName)) {
204	        aliases.push({
205	          name: element.name.text,
206	          baseHelper: importedName,
207	        });
208	      }
209	    }
210	  }
211	
212	  return aliases;
213	}
214	
215	function collectEvalCalls(
216	  sourceFile: ts.SourceFile,
217	  helpers: Record<string, BaseEvalHelper | 'unknown'>,
218	  onCall: (callExpression: ts.CallExpression, helperName: string) => void,
219	) {
220	  const visit = (node: ts.Node) => {
221	    const wrapperName = getFunctionLikeBindingName(node);
222	    if (wrapperName && helpers[wrapperName] && !isBaseEvalHelper(wrapperName)) {
223	      return;
224	    }
225	
226	    if (ts.isCallExpression(node)) {
227	      const helperName = getCalledIdentifierName(node);
228	      if (helperName && helpers[helperName]) {
229	        onCall(node, helperName);
230	      }
231	    }
232	
233	    ts.forEachChild(node, visit);
234	  };
235	
236	  visit(sourceFile);
237	}
238	
239	function findCalledHelper(
240	  functionNode: ts.Node,
241	  helpers: Record<string, BaseEvalHelper | 'unknown'>,
242	): string | undefined {
243	  let found: string | undefined;
244	
245	  const visit = (candidate: ts.Node) => {
246	    if (found) {
247	      return;
248	    }
249	    if (
250	      candidate !== functionNode &&
251	      (ts.isFunctionDeclaration(candidate) ||
252	        ts.isFunctionExpression(candidate) ||
253	        ts.isArrowFunction(candidate) ||
254	        ts.isMethodDeclaration(candidate))
255	    ) {
256	      return;
257	    }
258	    if (ts.isCallExpression(candidate)) {
259	      const helperName = getCalledIdentifierName(candidate);
260	      if (helperName && helpers[helperName]) {
261	        found = helperName;
262	        return;
263	      }
264	    }
265	    ts.forEachChild(candidate, visit);
266	  };
