8	
9	/**
10	 * @fileoverview CLI entry point for the eval inventory command.
11	 *
12	 * Scans all eval source files, runs the static analyzer on each,
13	 * and prints a human-readable inventory report grouped by policy,
14	 * file, and suite.
15	 *
16	 * Usage:
17	 *   npm run eval:inventory
18	 *   npm run eval:inventory -- --root /path/to/repo
19	 */
20	
21	import {
22	  collectInventory,
23	  formatInventoryReport,
24	} from './utils/eval-inventory.js';
25	
26	async function main() {
27	  const rootFlagIndex = process.argv.indexOf('--root');
28	  const repoRoot =
29	    rootFlagIndex !== -1 && process.argv[rootFlagIndex + 1]
30	      ? process.argv[rootFlagIndex + 1]
31	      : process.cwd();
32	
33	  const result = await collectInventory(repoRoot);
34	
35	  if (result.totalFiles === 0) {
36	    console.error('No eval files found under evals/.');
37	    process.exit(1);
38	  }
39	
40	  console.log(formatInventoryReport(result));
41	}
42	
43	main().catch((error) => {
44	  console.error('Fatal error:', error);
45	  process.exit(1);
46	});
