/**
 * Formats an InventoryResult into a structured, machine-readable JSON
 * report. All file paths are relative to the repo root and the output is
 * deterministic for identical inputs (given a fixed timestamp).
 *
 * The generation timestamp can be overridden for reproducible builds via
 * environment variables (see {@link resolveGeneratedDate}) or the optional
 * `now` argument.
 */
export function formatInventoryJson(
  result: InventoryResult,
  now?: Date,
): string {
  const relativePaths = buildRelativePathMap(result);

  const byPolicy: Record<string, number> = {};
  const counts = groupBy(result.cases, (c) => c.policy);
  const knownPolicies = POLICY_ORDER.filter((policy) => counts.has(policy));
  const unlistedPolicies = [...counts.keys()]
    .filter((policy) => !(POLICY_ORDER as string[]).includes(policy))
    .sort((a, b) => compareStrings(a, b));
  for (const policy of [...knownPolicies, ...unlistedPolicies]) {
    byPolicy[policy] = counts.get(policy)!.length;
  }

  const cases: InventoryJsonCase[] = result.cases.map((evalCase) => ({
    name: evalCase.name,
    filePath: toRelativePath(evalCase.filePath, result, relativePaths),
    helperName: evalCase.helperName,
    baseHelperName: evalCase.baseHelperName,
    policy: evalCase.policy,
    suiteName: evalCase.suiteName,
    suiteType: evalCase.suiteType,
    timeout: evalCase.timeout,
    hasFiles: evalCase.hasFiles,
    hasPrompt: evalCase.hasPrompt,
    location: evalCase.location,
  }));

  const diagnostics: InventoryJsonDiagnostic[] = result.diagnostics.map(
    (diagnostic) => ({
      severity: diagnostic.severity,
      message: diagnostic.message,
      filePath: toRelativePath(diagnostic.filePath, result, relativePaths),
      location: diagnostic.location,
    }),
  );

  const output: InventoryJsonOutput = {
    version: 1,
    generated: resolveGeneratedDate(now).toISOString(),
    summary: {
      totalFiles: result.totalFiles,
      totalCases: result.totalCases,
      totalDiagnostics: result.diagnostics.length,
      byPolicy,
    },
    cases,
    diagnostics,
  };

  return JSON.stringify(output, null, 2);
