/**
 * Resolves the timestamp used for the `generated` field. Environment
 * variables take precedence over the `now` argument so that reproducible
 * builds remain stable regardless of caller behavior:
 *
 *   - `SOURCE_DATE_EPOCH`: Unix timestamp in seconds.
 *   - `EVAL_INVENTORY_STABLE_DATE` / `EVAL_INVENTORY_DETERMINISTIC`: Unix epoch 0.
 *
 * Falls back to the provided `now`, then to the current time.
 */
function resolveGeneratedDate(now?: Date): Date {
  const sourceDateEpoch = process.env['SOURCE_DATE_EPOCH'];
  if (sourceDateEpoch !== undefined && sourceDateEpoch.trim() !== '') {
    const seconds = Number(sourceDateEpoch);
    if (Number.isFinite(seconds)) {
      return new Date(seconds * 1000);
    }
  }

  if (
    process.env['EVAL_INVENTORY_STABLE_DATE'] !== undefined ||
    process.env['EVAL_INVENTORY_DETERMINISTIC'] !== undefined
  ) {
    return new Date(0);
  }

  return now ?? new Date();
}

/**
 * Builds a lookup from absolute file path to repo-relative path using the
 * analyzed files.
 */
function buildRelativePathMap(result: InventoryResult): Map<string, string> {
  const relativePaths = new Map<string, string>();
  for (const file of result.files) {
    relativePaths.set(file.filePath, file.relativePath);
  }
  return relativePaths;
}

/**
 * Resolves a (possibly absolute) file path to a repo-relative path. Prefers
 * the analyzer-provided relative path, then computes one from the repo root,
 * leaving the sentinel `<inline>` path untouched.
 */
function toRelativePath(
  filePath: string,
  result: InventoryResult,
  relativePaths: Map<string, string>,
): string {
  if (filePath === '<inline>') {
    return filePath;
  }
  const mapped = relativePaths.get(filePath);
  if (mapped) {
    return mapped;
  }
  if (result.repoRoot) {
    return path.relative(result.repoRoot, filePath).replace(/\\/g, '/');
  }
  return filePath;
