/**
 * Resolves the timestamp used for the `generated` field. Environment
 * variables take precedence over the `now` argument so that reproducible
 * builds remain stable regardless of caller behavior:
 *
 *   - `SOURCE_DATE_EPOCH`: Unix timestamp in seconds.
 *   - `EVAL_INVENTORY_STABLE_DATE` / `EVAL_INVENTORY_DETERMINISTIC`: Unix epoch 0.
 *
 * Falls back to the provided `now`, then to the current time.
 */
function resolveGeneratedDate(now?: Date): Date {
  const sourceDateEpoch = process.env['SOURCE_DATE_EPOCH'];
  if (sourceDateEpoch !== undefined && sourceDateEpoch.trim() !== '') {
